base.src/checkout/stripe.ts:
export async function charge(confirmationTokenId: string): Promise<void> {
  await fetch(`/charge/${confirmationTokenId}`, { method: "POST" });
}

raised.src/checkout/pay.ts:
import { charge } from "./stripe";

export interface PayInput {
  confirmationTokenId?: string;
  savedPaymentMethodId?: string;
}

export async function pay(input: PayInput): Promise<void> {
  await charge(input.confirmationTokenId ?? "");
}

